@calculate_execution_time(func_id='MULTI_RAG.RETRIEVE_STRUCTURED_TEXT')
def retrieve_structured_text(self, query: str, context_list: List[Dict[str, Any]]) -> str:
    ret = construct_new_text_list(query, context_list, compressor=self.compress)
    return str(ret) + '（Notice：order越大，越接近当前query轮次）' if ret else ''

@calculate_execution_time(func_id='MULTI_RAG.RETRIEVE_RELATED_TEXT')
def retrieve_related_text(self, query: str, context_list: List[Dict[str, Any]]) -> str:
    # 如果上下文列表为空，返回空字符串
    if not context_list:
        return ""

    # 如果只有一个上下文，直接返回格式化后的内容
    if len(context_list) == 1:
        self.logger.log_info("【MULTI-RAG】检测到单一上下文")  # 记录日志
        return f"{context_list[0]['text']}:\n{context_list[0]['answer'][:self.max_length]}"

    # 构建完整的问答内容，包括所有上下文条目
    full_context_qa = "\n".join([
        f"ROUND: {item['order']}; <{item['text']}>: {item['answer']}"
        for item in context_list
    ])
    # 如果完整问答内容小于3000字符，返回它并附加提示
    if len(full_context_qa) < 3000:
        return full_context_qa + "\n(Notice: 查询更相关于后续轮次)"

    # 构建截断的问答内容，每个答案限制为500字符
    truncated_context_qa = "\n".join([
        f"ROUND: {item['order']}; <{item['text']}>: {item['answer'][:500]}"
        for item in context_list
    ])
    # 如果截断后的问答内容小于4096字符，返回它并附加提示
    if len(truncated_context_qa) < 4096:
        return truncated_context_qa + "\n(Notice: 查询更相关于后续轮次)"

    # 初始化处理后的检索文本
    processed_retrieved_text = ""

    # 遍历上下文列表，从每个上下文中提取相关段落
    for item in context_list:
        raw_text = item['answer']
        # 解析 Markdown 内容，提取标题、标题层级和段落
        headers, header_levels, paragraphs = process_markdown(raw_text)
        item['paragraphs'] = paragraphs  # 将段落信息存回上下文条目
        # 根据查询获取相关段落并拼接到检索文本中
        processed_retrieved_text += self.extract_related_paragraphs(query, headers, header_levels, paragraphs) + "\n"

    # 如果成功通过段落匹配提取到内容，返回处理后的结果
    if processed_retrieved_text:
        self.logger.log_info("【MULTI-RAG】通过段落匹配完成检索")  # 记录日志
        return f"{processed_retrieved_text}\n最后一轮: <{context_list[0]['text']}>:\n{context_list[0]['answer'][:self.max_length]}"

    # 如果段落匹配失败，回退到基于幻灯片的检索方法
    slide_retrieved_text = self.retrieve_by_slide(query, context_list)
    self.logger.log_info("【MULTI-RAG】通过幻灯片方法完成检索")  # 记录日志
    return f"{slide_retrieved_text}\n最后一轮: <{context_list[0]['text']}>:\n{context_list[0]['answer'][:self.max_length]}"


def extract_related_paragraphs(self, query: str, headers: List[str], header_levels: List[int], paragraphs: List[str]) -> str:
    related_text = ""
    # 计算查询与每个标题的相似度
    similarities = [difflib.SequenceMatcher(None, query, header).ratio() for header in headers]

    # 遍历标题和标题层级，根据相似度提取相关段落
    for idx, (similarity, level) in enumerate(zip(similarities, header_levels)):
        if similarity > self.threshold:
            while idx < len(header_levels) and level < header_levels[idx]:
                related_text += paragraphs[idx]
                idx += 1

    return related_text.strip()

def retrieve_by_rerank(self, query: str, text_list: List[Dict[str, Any]]) -> str:
    doc_list = []
    for idx, text_dict in enumerate(text_list):
        doc_list.append({"id": idx, "doc": text_dict['text']})
        for para in text_dict['paragraphs']:
            doc_list.append({"id": idx, "doc": para})

    params = {
        "query": query,
        "docList": doc_list,
        "model": "bge",
    }

    id_score_list = call_api(url=RAG_RERANK_URL, data=params)["data"]["resultList"]

    retrieved_text = ""
    for id_score in id_score_list:
        if id_score['score'] < self.threshold:
            break
        retrieved_text += doc_list[id_score['id']]['doc'] + "\n"

    return retrieved_text.strip()

def retrieve_by_slide(self, query: str, text_list: List[Dict[str, Any]]) -> str:
    bm25fqa = BM25FQA(text_list)
    top_answer = bm25fqa.get_top_answers(query, top_n=3)
    return top_answer.strip()
